<template><Teleport to="body"><Transition name="ui-drawer"><div v-if="modelValue" class="ui-drawer-layer" @click.self="close"><aside v-bind="$attrs" class="ui-drawer" :style="{ width: normalizedSize }"><header><h2>{{ title }}</h2><button type="button" @click="close">×</button></header><div class="ui-drawer__body"><slot /></div></aside></div></Transition></Teleport></template>
<script setup>
import { computed } from 'vue'
defineOptions({ inheritAttrs: false })
const props = defineProps({ modelValue: Boolean, title: String, size: { type: [String, Number], default: '380px' } }); const emit = defineEmits(['update:modelValue', 'close'])
const normalizedSize = computed(() => typeof props.size === 'number' ? `${props.size}px` : props.size); const close = () => { emit('update:modelValue', false); emit('close') }
</script>
<style scoped>.ui-drawer-layer { position: fixed; inset: 0; z-index: 2000; background: rgba(24,49,59,.35); backdrop-filter: blur(4px); }.ui-drawer { position: absolute; inset: 0 0 0 auto; max-width: calc(100vw - 24px); display: flex; flex-direction: column; background: var(--surface-card); box-shadow: -18px 0 50px rgba(24,49,59,.18); }.ui-drawer header { display: flex; align-items: center; justify-content: space-between; padding: 20px 24px; border-bottom: 1px solid var(--line); background: linear-gradient(135deg,var(--surface-subtle),#fff); }.ui-drawer h2 { margin: 0; color: var(--ink-strong); font-size: 18px; }.ui-drawer header button { width: 30px; height: 30px; border: 0; border-radius: 50%; background: transparent; color: var(--ink-muted); font-size: 24px; cursor: pointer; }.ui-drawer header button:hover { background: var(--brand-primary-soft); color: var(--brand-primary); }.ui-drawer__body { flex: 1; overflow: auto; padding: 24px; }.ui-drawer-enter-active,.ui-drawer-leave-active { transition: opacity .2s ease; }.ui-drawer-enter-active .ui-drawer,.ui-drawer-leave-active .ui-drawer { transition: transform .2s ease; }.ui-drawer-enter-from,.ui-drawer-leave-to { opacity: 0; }.ui-drawer-enter-from .ui-drawer,.ui-drawer-leave-to .ui-drawer { transform: translateX(100%); }</style>
